pub fn toObject(s: anytype, value: c.JSValue) !c.JSValue {
    var boundary: Boundary = .{ .engine = s.engine }; try boundary.begin();
    return boundary.finishValue(s, c.JS_ToObject(s.engine.context, value));
}

